export const categoryInterpretations: Record<string, string> = {
  "3 Monde (2018)":
    "\nThomas Richartz - Eine Stadt mit\ndrei Monden (2018)\n\nIm September 2018 verwandelte\nsich der „Kunst-Kiosk“ Yok Yok im\nFrankfurter Bahnhofsviertel in einen\nrituellen Kampfplatz gegen die\ndunklen Kräfte urbaner Gier. Mit der\nPerformance Eine Stadt mit drei\nMonden inszenierte \nThomas Richartz - Eine Stadt mit\ndrei Monden (2018)\n\nMit Eine Stadt mit drei Monden\npositioniert sich Thomas Richartz in\neiner performativen Tradition, die\nvon den rituell aufgeladenen\nAktionen der Wiener Aktionisten bis\nzu den sozialräumlichen\nInterventionen zeitgenössischer\nPerformancekunst reicht. Die im\n„Kunst-Kiosk“ Yok Yok inszenierte\nArbeit ist zugleich ein\nOrtskommentar und eine\nsymbolische Verdichtung der\nökonomischen, erotischen und\ntoxischen Dynamiken des\nFrankfurter Bahnhofsviertels.\n\n\nRichartz die Austreibung dreier\nDämonen, die wie unsichtbare\nHerrscher über das Viertel\nschweben: der Dämon der Geld-\nund Goldgier, der Dämon der\nsexuellen Gier und der Dämon der\nSucht nach Alkohol und Drogen.\nDrei „Exorzisten“ und ein\nZeremonienmeister führten ein\ndrastisches, symbolgeladenes Ritual\ndurch: Drei Pfähle wurden in drei\nToilettenschüsseln gerammt - ein\nAkt zwischen sakraler Geste und\naggressiver Entweihung. Jede\nSchüssel war präpariert, um bei der\nAktion Farbe zu verspritzen: Gold\nfür den unstillbaren Hunger nach\nReichtum, Rot für die triebhafte\nBegierde, Schwarz für den Rausch\nund die Selbstzerstörung.\nfür den unstillbaren Hunger nach\nReichtum, Rot für die triebhafte\nBegierde, Schwarz für den Rausch\nund die Selbstzerstörung.\n\nDas Publikum erlebte eine rohe,\nkörperliche, fast kathartische\nEntladung. Spritzer und Tropfen an\nden weißen Wänden wirkten wie\nSpuren eines Kampfes, dessen\nGegner nicht aus Fleisch und Blut,\nsondern aus den unsichtbaren\nStrukturen von Macht, Verlangen\nund Abhängigkeit bestanden.\nRichartz’ Arbeit verschränkt in\ndiesem Moment politische,\ngesellschaftliche und spirituelle\nEbenen - eine rituelle Bildsprache,\ndie zwischen Abwehrzauber und\nAbrechnung changiert.\n\nThomas Richartz - Eine Stadt mit\ndrei Monden (2018)\n\nIm September 2018, mitten im\npulsierenden und widersprüchlichen\nFrankfurter Bahnhofsviertel, erhob\nsich im „Kunst-Kiosk“ Yok Yok ein\nRaum der Beschwörung. Thomas\nRichartz verwandelte den engen Ort\nin eine Bühne für ein archaisch\nanmutendes Ritual: die Austreibung\ndreier Dämonen, deren unsichtbare\nGegenwart seit jeher die Straßen\nbeherrscht —- die unersättliche Gier\nnach Geld und Gold, die fiebrige\nGier des Fleisches und die dunkle\nGier nach Rausch und Vergessen. In\nder Mitte: drei Toilettenschüsseln,\nSinnbilder für die Verdauung und\nEntsorgung des Unreinen, \nübersät mit Spritzern, wurden zum\nstummen Zeugnis einer Schlacht\nohne Körper, aber voller Spuren.\n\nEine Stadt mit drei Monden ist mehr\nals eine Performance - es ist eine\nrituelle Anrufung, ein Versuch, das\nmoralische und emotionale\nGleichgewicht in einem Viertel zu\nerzwingen, das von Verlockung und\nVerfall gleichermaßen durchzogen\nist. In Richartz’ Inszenierung\nverschränken sich das Sakrale und\ndas Profane, das Theater des\nKörpers und die Alchemie der Farbe,\nbis sie sich in einer einzigen Frage\nauflösen: Kann man Dämonen\nwirklich vertreiben — oder nur ihre\nNamen rufen, um ihnen zu\nbegegnen?\n\nProfane Thronsitze der Dämonen. In\nsie wurden drei spitze Pfähle\ngerammt - ein Akt von Gewalt und\nBefreiung, ein Schlag gegen das\nUnsichtbare.\n\nMit jedem Hieb schossen Farben\ndurch den Raum: Gold wie der\nverführerische Glanz des Reichtums,\nRot wie das pochende Blut der\nBegierde, Schwarz wie der zähe\nSchatten der Sucht. Die Wände,\nübersät mit Spritzern, wurden zum\nstummen Zeugnis einer Schlacht\nohne Körper, aber voller Spuren\n\nThomas Richartz - Eine Stadt mit\ndrei Monden (2018)\n\nMit Eine Stadt mit drei Monden\npositioniert sich Thomas Richartz in\neiner performativen Tradition, die\nvon den rituell aufgeladenen\nAktionen der Wiener Aktionisten bis\nzu den sozialräumlichen\nInterventionen zeitgenössischer\nPerformancekunst reicht. Die im\n„Kunst-Kiosk“ Yok Yok inszenierte\nArbeit ist zugleich ein\nOrtskommentar und eine\nsymbolische Verdichtung der\nökonomischen, erotischen und\ntoxischen Dynamiken des\nFrankfurter Bahnhofsviertels.\n\n„Kunst-Kiosk“ Yok Yok inszenierte\nArbeit ist zugleich ein\nOrtskommentar und eine\nsymbolische Verdichtung der\nökonomischen, erotischen und\ntoxischen Dynamiken des\nFrankfurter Bahnhofsviertels.\nRichartz’ Wahl der Bildträger —-\nToilettenschüsseln —- bricht bewusst\nmit der Vorstellung einer\n„neutralen“ künstlerischen\nOberfläche. Stattdessen wird der\nOrt der Ausscheidung zum Altar der\nDämonen, der Pfahl zum Speer des\nExorzismus. Die performative Geste\ndes Hineinrammens ist aggressiv,\nkathartisch und irreversibel; sie\ntransformiert das Banale ins Sakrale\nund das Sakrale ins Politische.\n\nDie farbcodierte Dreiteilung (Gold,\nRot, Schwarz) folgt einer klaren\nSemantik: Gold für monetäre\nObsession, Rot für sexuelle\nBegierde, Schwarz für den Sog von\nRauschmitteln. Diese\nFarbexplosionen an den weißen\nWänden erinnern an gestische\nMalerei, verweisen jedoch zugleich\nauf Spuren von Gewalt, Unfällen\noder Verbrechen - ein bewusstes\nSpiel mit ästhetischer Ambivalenz.\nIn kunsthistorischer Perspektive\nlässt sich Richartz’ Performance als\nHybrid lesen: Sie vereint das rituelle\nPathos der Aktionskunst der\n1960er-Jahre, den gesellschaftskritischen \nImpuls der 1970er \n1970er und eine zeitgenössische\nSensibilität für urbane Mikrokosmen.\nDurch die situative Bindung an das\nBahnhofsviertel fungiert die Arbeit\nals ortsspezifischer Exorzismus —-\nweniger als Versuch, Dämonen\nendgültig zu vertreiben, sondern als\nSichtbarmachung ihrer\nunausweichlichen Präsenz.\n\nSo wird Eine Stadt mit drei Monden\nzu einem Spiegel der Stadt selbst:\nein Raum, in dem Verheißung und\nVerderben in einem unauflöslichen\nKnoten zusammenfinden.\n\n\n\n\n\n\n\n",
  "32 Denkmäler (1993-1999)":
    '\nThomas Richartz - 32 Denkmäler\n(1993-1999)\n\nZwischen 1993 und 1999 entstand\nmit der Serie „32 Denkmäler“ ein\nWerkzyklus, der gleichermaßen\narchaisch und zeitgenössisch wirkt.\nDer Ausgangspunkt war\nunscheinbar:während seiner  \nTätigkeit in einer Baustofffirma\nerhielt Thomas Richartz Zugang zu\neiner großen Menge Ytong-Bruch —\nein industriell gefertigtes, leicht zu\nbearbeitendes Material, das für ihn\nzum idealen Medium wurde. Mit diesem Fund konnte Richartz\neinen lange gehegten Plan\nverwirklichen: eine Reihe von\nSkulpturen zu schaffen, die er\nbewusst unter den Arbeitstitel „32\nDenkmäler für den unbekannten\nKünstler“ stellte - eine direkte\nAnspielung auf das „Denkmal für\nden unbekannten Soldaten“. Damit\nverlagert er die Geste des\nGedenkens vom militärischen\nHelden hin zum anonymen\nschöpferischen Geist, der außerhalb\nvon Ruhm und Markt existiert.\n\nDie Skulpturen selbst oszillieren\nzwischen architektonischem\nFragment und symbolischer Form.\nSie erinnern an ruinöse Säulen,\nstilisierte Maschinen, totemartige\nStelen - Monumente ohne klaren\nAuftraggeber, die dennoch eine\nstille Autorität ausstrahlen. Durch\nden Einsatz des poröse Ytong\nentstehen Oberflächen, die\ngleichermaßen brüchig wie massiv\nerscheinen; sie tragen die Spuren\nvon Bearbeitung und Verfall in sich\nund verweisen so auf Zeitlichkeit\nund Vergänglichkeit.\n\nÜber sechs Jahre hinweg\nentwickelte Richartz diese Serie,\njede Skulptur ein eigenes\n„Denkmal“, doch gemeinsam bilden\nsie ein kollektives Gedächtnis an\njene, die künstlerisch wirken, ohne\nSpuren in den Annalen der\nKunstgeschichte zu hinterlassen.\n„32 Denkmäler“ ist somit nicht nur\nein plastisches Projekt, sondern\nauch ein stiller Kommentar über\nSichtbarkeit, Anerkennung und das\noft unsichtbare / Fundament\nkultureller Produktion.\n\nThomas Richartz - 32 Denkmäler\n(1993-1999)\n\nAus den Resten einer Baustofffirma,\naus Bruchstücken von Ytong, wuchs\neine stille Stadt aus Zeichen.\nZwischen 1993 und 1999 schuf\nThomas Richartz zweiunddreißig\nSkulpturen - zweiunddreißig\nDenkmäler für den unbekannten\nKünstler.\n\nSie sind keine heroischen\nStandbilder, keine Triumphbögen,\nkeine Namen in Stein. Es sind\nFormen, die an Tempelruinen\nerinnern, an Maschinen, die längst\nverstummt sind, an Stelen, die\nschweigend von einer vergessenen\nGeschichte künden. Das brüchige\nMaterial trägt die Narben der\nBearbeitung, als hätte es selbst\neinen langen Weg hinter sich - vom\nAbfallhaufen zur Trägerin von\nErinnerung.\n\nJedes Denkmal ist ein Echo, das sich\nnicht auf eine einzelne Stimme\nrichtet, sondern auf all jene, die\nohne Signatur arbeiten. Es ist eine\nSammlung aus stummen\nWidmungen, errichtet für das\nunsichtbare Heer der Schaffenden,\nderen Werke kein Museum bewahrt.\nSo stehen sie nun - leicht und doch\nmassiv, verletzlich und doch trotzig\n— wie eine Landschaft aus\nGedenken. Ein Ort, an dem das\nVergängliche und das Unvergessene\nineinander übergehen.\n\n"32 Denkmäler" von Thomas Richartz\n\nAus den Scherben des Alltags, aus\nden Trümmern einer gewöhnlichen\nExistenz, erhebt Thomas Richartz\nseine stummen Zeugen. Sechs Jahre\nlang, von 1993 bis 1999, wuchs in der\nStille seiner Werkstatt ein Pantheon\ndes Unbekannten. Nicht aus Marmor\noder Bronze, sondern aus\nY-tong-Bruchstücken, dem\nunscheinbaren Abfall einer\nBaustofffirma, formte er seine\nDenkmäler. Ein pathetischer Akt der\nAuflehnung gegen die Vergessenheit von\n\nSchweiß, Mühe und der Beharrlichkeit\ndes Schaffens. Jedes Stück Y-tong,\neinst ein Bruchstück, wird in Richartz\'\nHänden zu einem Mosaikstein der\nErinnerung. Diese Denkmäler sind\nkeine glatten, polierten Abbilder der\nMacht, sondern rauhe, ungeschliffene\nZeugnisse einer inneren Wahrheit. Sie\nfordern uns auf, genauer hinzusehen\n— auf die Schönheit im Zerbrochenen,\nauf die Würde im Verborgenen. Sie\nsind das Vermächtnis des Künstlers,\nder uns daran erinnert, dass wahre\nKunst nicht im Ruhm, sondern in der\nLeidenschaft des Schaffens selbst\nliegt.\n\n\n\n\n\n',
  "Africa-Europa (2016)":
    "\nAfrika/Europa: \n\nDie Installation , Afrika/Europa”\nmanifestiert die vielschichtige und oft\nwidersprüchliche Beziehung\nzwischen den beiden Kontinenten. Sie\nist ein visuelles Gespräch, das sich\nüber physische und metaphorische\nGrenzen hinweg erstreckt.\nIm Zentrum des Werkes stehen zwei\nungleiche Elemente, die in einem\nZustand von Balance und Spannung\nzueinander in Beziehung gesetzt\nwerden: Die archaisch anmutende,\nerdige Form, die an afrikanische\nSkulpturen oder Landschaften\nerinnert, trifft auf eine filigrane, fast\nfuturistische Struktur aus\neuropäischen Industriematerialien.\nDieses Aufeinandertreffen ist kein\nharmonisches Verschmelzen,\nsondern eine dynamische\nAuseinandersetzung, die Fragen nach\nGeschichte, Kolonialismus, Migration\nund kultureller Identitat aufwirft.\n\nDie Installation spielt mit\nGegensätzen — Schwere und\nLeichtigkeit, Tradition und Moderne,\nNatur und Technik — um die\nkomplexen Verflechtungen zu\nverdeutlichen, die das Schicksal\nbeider Kontinente unwiderruflich\nmiteinander verbunden haben. Sie ist\nein stilles Denkmal für die\nVergangenheit und zugleich ein\nKommentar zur Gegenwart, der den\nBetrachter einlädt, über die\ngemeinsamen Wurzeln und die\ngeteilte Zukunft von Afrika und\nEuropa nachzudenken.\n\n\n",
  "Ametat (2020)":
    '\nAmetat\nInstallation von Thomas Richartz\n\nAmetat — ein athiopisches Wort fur\n"Ursprung” — ist die Suche nach den\nAnfangen unserer menschlichen\nNatur. Die Installation verbindet\ngroßformatige Mauer-Frottagen mit\norganischen und mineralischen\nElementen: Samen in den Hülsen\ndes Affenbrotbaums und Steine, die\nan Ästen hängen.\n\nDie Mauern stehen für einen\nentscheidenden Wendepunkt in der\nFrühgeschichte: den Beginn des\nBauens als Schutz vor einer\nbedrohlichen Umwelt und als Mittel\nzur Vorratshaltung. Es ist der\nMoment, in dem der Mensch\nbeginnt, Raum zu definieren — ein\n"Innen" zu schaffen und ein\n"Außen" auszugrenzen.\n\nDie Samen des Affenbrotbaums\nverweisen auf die triebgesteuerten\nInstinkte der Anfangszeit — den\nUrimpuls zur Ernährung, zur\nSelbsterhaltung, zur Reproduktion.\nIhnen gegenüber stehen die\nschwebenden Steine: eine Metapher\nfür den Aufstieg des Geistes, der\ndie Schwerkraft der Instinkte\nüberwindet. Sie sind Sinnbilder für\nden Schritt vom bloßen Überleben\nhin zum bewussten, geistigen\nGestalten der Welt.\n\nIn der Reduktion auf wenige,\nelementare Materialien öffnet\nAmetat einen stillen Denkraum über\nden Ursprung — und darüber, wie\nsehr wir noch heute zwischen\nSchutzbedürfnis und geistigem\nAufbruch stehen.\n\n\n\nAmetat\n\nSamen, schwer von Ursprung.\nSteine, aufgehoben ins Schweben.\nMauern, die schutzen — und trennen.\nZwischen Instinkt und Geist\nspannt sich der erste Bogen\nmenschlicher Geschichte\n\nAmetat / Corona-Art (2020)\nThomas Richartz\n\nAmetat — "Ursprung" — ist eine\nkünstlerische Spurensuche nach\nden Anfängen: dem ersten\nAufkeimen von Materie, dem Beginn\nmenschlicher Kultur, den Schritten\nvom Instinkt zum Geist.\n\nDer erste Teil, als Installation,\nverbindet Mauer-Frottagen, Samen\ndes Affenbrotbaums und hängende\nSteine zu einer archaischen\nErzählung. Mauern werden zu\nSymbolen für Schutz und\nVorratshaltung, Samen fur das\ntriebhafte Fundament, Steine im\nSchweben für den geistigen\nAufstieg über die Schwerkraft der\nInstinkte hinaus. \n\n\n\nDer zweite Teil, ursprünglich\nebenfalls unter dem Titel Ametat\ngeplant, wurde durch den Ausbruch\nder Corona-Pandemie zu\n"Corona-Art"\nIn Lasurmalerei auf Reflektorkarton\nentstehen abstrakte Bildräume, die\nden Ursprung der materiellen Welt\nmeditativ erfahrbar machen.\nZugleich spiegeln sie die\nUnsicherheit und Verletzlichkeit\neiner Zeit, in der Grenzen zwischen\nInnen und Außen, Schutz und\nIsolation, Ursprung und Neubeginn\nneu verhandelt wurden.\n\n\nGemeinsam sind beide\nWerkgruppen eine Einladung, in den\nResonanzraum von Vergangenheit\nund Gegenwart einzutreten -\ndorthin, wo Anfang und Ende nicht\nabgeschlossen sind, sondern immer\nwieder neu entstehen.\n\n\n\n\n\n',
  "Auswahl 1 (1995-2008)":
    '\n\nThomas Richartz\n\nZwischen 1995 und 2008 entfaltet\nsich in diesen Arbeiten ein visuelles\nArchiv des Fragens und Erinnerns.\nThomas Richartz verbindet in seiner\nSerie das Flüchtige der Lasur mit\nder Direktheit figürlicher\nAnspielungen. Jedes Bild steht für\nsich, doch gemeinsam wirken sie\nwie eine mehrstimmige Erzählung:\nFragmente von Mythen, historische\nVersatzstücke, abstrakte Strukturen\nund organische Spuren, gebettet in\nein komplexes Farbspektrum.\n\nDie Werke oszillieren zwischen\nAbstraktion und Erzählung.\n\nMal dominiert ein reines\n\n\n\nMal dominiert ein reines\nFarb-Geschehen - kühle Blautöne,\nglühendes Rot, verhaltenes Ocker —\nwie Echos von Naturprozessen, die\nsich in Oberflächen einschreiben.\nMal treten Figuren auf: antike\nGötterkopfe, Krieger mit Schilden,\nSkelettgestalten, allegorische\nFrauenfiguren. Sie blicken uns aus\nder Geschichte entgegen, entrückt\nund doch vertraut, wie aus einer\nkollektiven Erinnerung\nherausgefiltert.\n\nEs entsteht ein Spannungsfeld aus\nNahe und Distanz: Die figürlichen\nMotive verankern den Blick,\nwährend die abstrakten Lasuren ihn\nins Unbestimmte führen. Die\n\n\nins Unbestimmte fuhren. Die\nmalerische Schichtung wird so zu\neiner Zeitreise — nicht linear,\nsondern vielschichtig, überlagernd,\nassoziativ.\n\nIn dieser Vielfalt begegnet der\nBetrachter einer Bildwelt, in der das\nVergangene nie abgeschlossen ist,\nsondern in neuen Formen\nwiederkehrt.\n\n"Auswahl 1" ist damit weniger eine\nthematisch geschlossene Serie als\nein Mosaik von Bildgedanken aus\ndreizehn Jahren. Es sind Bilder, die\nGeschichten bergen, ohne sie\nvollständig zu erzählen, und Spuren\nhinterlassen, die weiterwirken — wie\nErinnerungen, die sich in Farbe\nverwandelt haben.\nThomas Richartz\n\nDiese Serie vereint dreizehn Jahre\nkünstlerischer Arbeit — ein Mosaik\naus abstrakten Lasuren, figürlichen\nAnspielungen und mythischen\nFragmenten.\n\nZwischen kühlen Blauflächen,\nglühenden Rottönen und erdigen\nStrukturen treten Gestalten auf:\nGötterkopfe, Krieger, Skelette,\nallegorische Figuren.\n\nRichartz verbindet Historie und\nGegenwart, Form und Auflösung, zu\neiner vielschichtigen Bildwelt, in der\ndas Vergangene fortlebt und sich in\nneuer Gestalt offenbart.\n\n\n\n\n\n',
  "Auswahl 2 (2008-2013)":
    '\nThomas Richartz — Auswahl 2\n(2008-2013)\nNach der Auseinandersetzung mit der\nSkulpturen-Serie "32 Denkmaler" und\nden großformatigen Acryl-Bildern der\n"Auswahl 1 (1995-2008)", die\nKunstgeschichte und persönliche\nErfahrungen reflektierten, wandte\nsich Thomas Richartz mit der Serie\n"Auswahl 2 (2008-2013)" neuen\nmalerischen Wegen zu.\nIn diesen Werken versucht der\nKünstler, die Grenzen zwischen\nabstrakter Struktur und feiner\nZeichnung aufzulösen. Die Bilder sind\ngeprägt von einem intensiven Spiel\naus explosiven Farbschichten und\nsorgfältig ausgearbeiteten, immer\nstarker betonten Umrisslinien. Diese\nverbinden sich mit dynamischen,\nkalligraphischen Elementen, die den\nKompositionen eine kraftvolle und\nzugleich flieBende Dynamik verleihen.\nRichartz\' Malerei in dieser\nSchaffensperiode ist ein Dialog\nzwischen spontanem Ausdruck und\nkontrollierter Form, der zu komplexen,\nvielschichtigen Oberflächen fuhrt, die\nden Betrachter zur Entdeckung neuer\nvisueller Ebenen einladen.\n\n\n\n\n',
  "Bilder (1995-2008)":
    '\nThomas Richartz:\n“Bilder” (1995-1999)\n\nDie Serie ,Bilder” (1995-1999) von\nThomas Richartz markiert einen\nentscheidenden Moment in seinem\nkünstlerischen Schaffen und\noffenbart eine frühe\nAuseinandersetzung mit den Themen\nUrsprung, Kosmos und die Schöpfung\nvon Welt. Ursprünglich unter dem\nArbeitstitel "Genesis" konzipiert,\nspiegeln diese Werke die Faszination\ndes Künstlers für die Entstehung von\nMaterie und die unendliche Weite des\nUniversums wieder.\n\nRichartz verwendet in dieser Serie\neine einzigartige Technik:\nLasurmalerei auf Reflektor-Karton.\nDieser unkonventionelle Träger, der\nnormalerweise für reflektierende\nOberflächen in der Industrie oder im\nStraßenverkehr genutzt wird, dient\nhier als schimmernde Leinwand, die\ndas Licht auf unerwartete Weise\nzurückwirft. Die Lasurmalerei, bei der\ndünne, transparente Farbschichten\nübereinandergelegt werden, erzeugt\neine Tiefe und Leuchtkraft, die den\nBetrachter in eine makrokosmische\nWelt entführt.\n\nIn der Gegenüberstellung von\nindustriellem Material und einer fast\nspirituellen, kosmischen Ästhetik liegt\ndie eigentliche Spannung dieser\nWerke. Richartz verschmilzt das\nProfane mit dem Erhabenen und\nschafft so eine bildnerische Sprache,\ndie das Technische und das\nPoetische miteinander verbindet. Die\nSerie "Bilder 1995-1999" ist somit nicht nur eine\nmalerische Erkundung des\nWeltraums, sondern auch eine\nmeditative Reise in die Anfänge der\nExistenz und ein Zeugnis für die\nunendliche Schöpferkraft, die in der\nKunst selbst liegt.\n\n\n\n',
  "Bilder (1995-1999)":
    "Zwölf Lasurmalereien - zwölf Stationen einer stillen Erkundung. Schicht um Schicht legt sich Farbe über die Fläche, durchlässig und zugleich verschlossen. Kühle Blau- und Violetttöne treffen auf rostige Wärme, vertikale Bahnen gliedern den Raum wie Mauern oder Säulen einer unsichtbaren Architektur. ... ",
  "Wege aus dem Ghetto (2016)":
    '"Kunst und so (2020/2021)\n\nIn der Serie "Kunst und so" widmet\nsich Thomas Richartz der\nNeuinterpretation kunsthistorischer\nBildmotive. In grafisch reduzierten,\nschwarz-weißen Acrylgemälden\ntransformiert er ikonische Werke\nder Kunstgeschichte in eine\neigenständige, zeitgenössische\nFormensprache. Durch den Verzicht\nauf Farbe und den konsequenten\nEinsatz von Hell-Dunkel-Kontrasten\nentsteht eine rhythmische, fast\nornamentale Struktur, die den Blick\nauf Linienführung, Komposition und\nformale Essenz lenkt.\n\nDas Werk Die Rückkehr des Vaters\ngreift sowohl auf die Bildwelt eines\nrömischen Reliefs als auch auf eine\nBoccioni zurück. Beide Referenzen\nverschmelzen in einer\nabstrakt-tektonischen\nSchwarz-Weiß-Architektur, die\nsowohl historische Tiefe als auch\nzeitgenössische Fragmentierung\nspürbar macht. Richartz’ Vorgehen\ngleicht einer archäologischen\nÜbersetzung: Er reduziert, schichtet\nund rekonstruiert, bis aus der\nVorlage eine autonome, visuell\nverdichtete Erzählung entsteht.\n\nSo wird "Kunst und so" zu einer Serie,\ndie nicht nur Kunstgeschichte\nzitiert, sondern sie in eine neue,\nmeditative Bildsprache überführt —-\nzwischen Hommage,\nDekonstruktion und\neigenständigem Ausdruck.\n\n\n\nKunst und so (2000-2021)\n\nIn Kunst und so transformiert\nThomas Richartz ikonische Werke\nder Kunstgeschichte in grafisch\nreduzierte, schwarz-weiße\nAcrylgemälde. Durch klare Linien,\nstarke Kontraste und formale\nVerdichtung entstehen\nzeitgenössische\nNeuinterpretationen historischer\nMotive.\n\nDas Werk Die Rückkehr des Vaters\nverbindet ein römisches Relief mit\neiner Skulptur von Umberto\nBoccioni und übersetzt beide in eine\nabstrahierte, ornamentale\nBildsprache. So entsteht eine Serie\nzwischen Hommage und\nDekonstruktion — ein Dialog von\nVergangenheit und Gegenwart in\nSchwarz und Weiß.\nGeschichte in Schwarz und\nWeiß — neu gedacht, neu\ngesehen.\n\nIkonen der Kunst — zerlegt,\nverdichtet, verwandelt.\n\nVon Rom bis Futurismus:\nVergangenheit trifft Gegenwart.\n\nKunstgeschichte, neu\nkomponiert — schwarz, weiß,\nzeitlos.\n\nFormen sprechen. Linien\nerinnern. Kunst bleibt.\n\n\n\n\n\n\n\n\n',
  "Dovcenko2 (2022)":
    '\n"Arsenal": Eine Serie von Gemälden\nvon Thomas Richartz\n\nDiese Serie von Acrylgemälden mit\ndem Titel , Arsenal” ist eine fesselnde\nAuseinandersetzung mit der\nFilmgeschichte und der Kunst der\nPorträtmalerei. Der Künstler Thomas\nRichartz hat sich hierbei von den\nausdrucksstarken Gesichtern und\nMomenten des berühmten\nStummfilms “Arsenal” (1928) des\nukrainischen Regisseurs Oleksandr\nPetrowytsch Dowschenko inspirieren\nlassen.\nEntstanden während der Zeit der\nCorona-Pandemie, spiegeln die\nWerke eine intensive\nAuseinandersetzung mit den\nmenschlichen Emotionen und den\ndramatischen Narrativen des Films\nwider. Richartz\' naturalistischer\nMalstil ist präzise und detailreich,\nwodurch er die pathetischen\nGesichtsausdrücke und die rohe\nIntensitat der Charaktere auf\neindrucksvolle Weise einfängt.\n\nJedes Porträt ist ein eigenständiges\nKunstwerk, das die Stimmung und die\nErzählung des Films in sich tragt,\nohne den Kontext des bewegten\nBildes zu verlieren.\n\nDie Gemäldeserie "Arsenal" ist eine\nHommage an die revolutionäre\nAsthetik des sowjetischen Kinos und\ngleichzeitig eine moderne\nInterpretation der menschlichen\nAusdrucksformen. Sie lädt den\nBetrachter ein, in die Tiefe der\ndargestellten Emotionen\neinzutauchen und die zeitlose Kraft\nder Porträtkunst zu erfahren.\n\n',
  "CORONA-ART (2020)":
    '\nCorona-Art (2020)\nvon Thomas Richartz\nUrsprünglich unter dem Titel\n»Ametat" konzipiert — einem\nathiopischen Wort, das ,,Ursprung*\nbedeutet — widmete sich diese\nWerkreihe der Frage nach dem\nBeginn der materiellen Welt.\nAusgangspunkt war eine meditative\nAnnäherung an die Genesis, an\njenes kaum fassbare Moment, in\ndem Form, Farbe und Struktur aus\ndem Unbestimmten hervorbrechen.\nDie Ausstellung war für das Frühjahr\n2020 geplant. Doch der weltweite\nAusbruch der Corona-Pandemie\nverhinderte ihre Eröffnung. Was als\nkontemplative Reise in die\nUrsprünge gedacht war, wurde\nzugleich zu einem Spiegel unserer\nGegenwart — einer Zeit, in der das\nLeben selbst plötzlich fragil,\nverletzlich und von unsichtbaren\nKraften geformt erschien.\n\nDie Technik der Lasurmalerei auf\nReflektorkarton erweist sich als\nbesonders geeignet für solche\nVorstellungen: Schicht für Schicht\nentstehen Tiefenraume, in denen\ndas Licht in wechselnden Winkeln\nreflektiert und gebrochen wird.\nDiese changierenden Oberflachen\nladen den Betrachter dazu ein,\ninnezuhalten und den Blick unter die\nsichtbare Schicht zu richten - so wurde die Ausstellung\nZugleich zu einem Spiegel unserer\nGegenwart — einer Zeit, in der das\nLeben selbst plötzlich fragil,\nverletzlich und von unsichtbaren\nKräften geformt schien.\n\nDie Technik der Lasurmalerei auf\nReflektorkarton erweist sich als\nbesonders geeignet für solche\nVorstellungen: Schicht fur Schicht\nentstehen Tiefenraume, in denen\ndas Licht in wechselnden Winkeln\nreflektiert und gebrochen wird.\nDiese changierenden Oberflachen\nladen den Betrachter dazu ein,\ninnezuhalten und den Blick unter die\nsichtbare Schicht zu richten - so\nwie man im Nachdenken Uber\nUrsprung und Werden unter die\nOberfläche der Welt zu dringen\nversucht.\n\nCorona-Art ist damit nicht\nnur eine Serie von Bildern, sondern\nein doppelter Resonanzraum:\nzwischen der inneren Meditation\nUber den Anfang und der\nErfahrung einer historischen Zäsur.\n\n\nCorona-Art (2020)\n\nAmetat —- ,Ursprung” — war der\nerste Name dieser Bilder.\n\nSie erzahlen vom Beginn, von jenem\nleisen Moment,\n\nin dem Materie Form annimmt\n\nund das Unsichtbare sichtbar wird.\nDann kam das Jahr 2020.\n\nDie Türen der Welt schlossen sich,\nund die Werke, die vom Anfang\nsprechen,\n\nwurden Teil einer anderen\nGeschichte -\n\neiner Zeit, in der auch wir\n\nneu begreifen mussten,\n\nwie verletzlich alles ist.\n\nSchicht um Schicht legt die\nLasurmalerei\n\nauf Reflektorkarton feine Häute aus\nLicht.\n\nSie spiegeln, brechen, verbergen —\nwie die Welt selbst.\n\n\n\n\n\n\n\n\n\n\n\n',
  "Büro (2019)":
    '\nTitel: Die Geburt des erweiterten\nKunstbegriffs aus dem Geist der\nFünfziger Jahre\nKünstler: Thomas Richartz\nAusstellung: “Büro 2018"\n\nThomas Richartz\'s Installation "Die\nGeburt des erweiterten Kunstbegriffs\naus dem Geist der Fünfziger Jahre"\nist ein faszinierender und\nvielschichtiger Beitrag zur\nAusstellung "Büro 2018". In einem\nehemaligen Büroraum inszeniert\nRichartz ein poetisches und zugleich\nThomas Richartz\'s Installation "Die\nGeburt des erweiterten Kunstbegriffs\naus dem Geist der Fünfziger Jahre"\nist ein faszinierender und\nvielschichtiger Beitrag zur\nAusstellung "Büro 2018". In einem\nehemaligen Büroraum inszeniert\nRichartz ein poetisches und zugleich\nkritisches Szenario, das die\nwirtschaftliche und kulturelle\nAufbruchsstimmung der\nNachkriegszeit mit den\nkünstlerischen Entwicklungen der\nAvantgarde verbindet.\n\nDie Installation besteht aus 17 an der\nDecke hängenden Filmmagazinen der\nFünfziger Jahre, die als Zeitkapseln\nkollektiver Träume und Sehnsüchte\nfungieren. Von jedem Magazin führt\nein Kupferkabel herab, das diese\n“Träume" symbolisch ableitet. Die\nKabel münden in zwei Packungen\nKüchenfett, die auf einem alten\nHolzstuhl platziert sind. Dieser Stuhl,\neine Reminiszenz an den berühmten\n"Fettstuhl" von Joseph Beuys, bildet\nden konzeptuellen Anker der Arbeit.\nRichartz\'s Werk schafft eine Brücke\nzwischen der Asthetik des\nWirtschaftswunders und dem\nerweiterten Kunstbegriff von Beuys.\nDas "Fett" steht dabei nicht nur für\ndie materiellen Uberflüsse und die\nwirtschaftliche "Schmiere" der\nFünfziger Jahre, sondern auch für die\nEnergie, die Beuys als kreatives\nPotenzial verstand. Die Installation\nlegt nahe, dass die kreative Kraft, die\nin den Alltagsträumen der Menschen\nschlummert, eine transformative\nEnergie ist, die den Weg für neue\nDie Verbindung von Trivialem\n(Küchenfett, Filmmagazine) und\nKünstlerischem (Beuys\'s Fettstuhl)\nhinterfragt die Grenzen der Kunst und\nreflektiert über die Ursprünge des\nerweiterten Kunstbegriffs. Richartz\nzeigt, wie die alltäglichen Phänomene\nder Nachkriegsgesellschaft - die\nKonsumträume, die Hoffnung auf\nFortschritt und Wohlstand - als\nNährboden für eine neue, offene\nKunstauffassung dienen konnten.\nerweiterten Kunstbegriffs. Richartz\nzeigt, wie die alltäglichen Phänomene\nder Nachkriegsgesellschaft - die\nKonsumträume, die Hoffnung auf\nFortschritt und Wohlstand - als\nNährboden für eine neue, offene\nKunstauffassung dienen konnten.\n"Die Geburt des erweiterten\nKunstbegriffs aus dem Geist der\nFünfziger Jahre" ist somit eine\nHommage an die kreative Kraft des\nAlltäglichen und ein intelligenter\nKommentar zur Rezeption und\nEntwicklung der Kunst in der zweiten\nHälfte des 20. Jahrhunderts\nder künstlerische Denkweisen ebnet.\nTitel: Das haben wir schon immer so\ngemacht, da konnt ja jeder kommen\nKlnstler: Thomas Richartz\nAusstellung: "Büro"\nOrt: Ehemaliger Bürotrakt im\nFrankfurter Gallus-Viertel\n\nThomas Richartz\'s installative\nSkulptur "Das haben wir schon immer\nso gemacht, da könnt ja jeder\nkommen" ist eine bissige und präzise\nAuseinandersetzung mit den\nMechanismen der Bürokratie und der\ndarin liegenden Trägheit. Als zweiter\nBeitrag des Künstlers zur Ausstellung\n\n"Büro" im Frankfurter Gallus-Viertel,\nnutzt die Arbeit einen gefundenen\nOrt und dessen Inventar, um eine\nmetaphorische Erzählung über\nStillstand und starre Strukturen zu\nentwickeln.\n\n\nIm Zentrum der Installation steht ein\nalter Aktenschrank, ein\narchetypisches Symbol für\nVerwaltung und die Archivierung von\nWissen und Regeln. In seinem\nInneren, wo einst Akten und\nDokumente die Ordnung der\nBürokratie festlegten, liegen nun\nBeton-Armierungseisen. Diese Eisen,\ndie eigentlich für Stabilitat und\nNeubau stehen, sind hier zu bloBen\nRelikten geworden — ihrer\neigentlichen Funktion entledigt und in\neiner starren, nutzlosen Anordnung\ngefangen.\nLose installierte Drähte verbinden\ndiese Eisen mit einer alten\nSchreibmaschine, die auf der Ablage\ndes Schranks ruht. Die\nSchreibmaschine, als Werkzeug der\nBürokratie par excellence, wird hier\nzum Ende einer Kette. Sie ist nicht\nmehr das Medium, um neue Ideen\noder Lösungen zu formulieren,\nsondern scheint die eingefrorene\nVerbindung zu den unbeweglichen\nEisen zu sein. Die Drähte suggerieren\neine fehlerhafte oder unterbrochene\nKommunikation, eine Art von\nKurzschluss in einem System, das\nnicht mehr in der Lage ist, sich \nselbst zu erneuern\n\n\nDer Titel der Arbeit, "Das haben wir\nschon immer so gemacht, da könnt ja\njeder kommen", ist eine direkte\nAnspielung auf einen Standardspruch\nder Verwaltungsbürokratie. Er\nillustriert die Abwehrhaltung\ngegenüber Innovation, die Angst vor\ndem Unbekannten und die\nVerfestigung von Regeln, die längst\nihren ursprünglichen Zweck verloren\nhaben. Richartz\'s Skulptur visualisiert\ndieses “Evolution-Stagnierungspotenzial*\nauf eindrucksvolle Weise. Sie ist eine\nphysische Manifestation des\nbürokratischen Stillstands, in der die\nEisen die unbeweglichen, starren\nRegeln und die Schreibmaschine die\nresignierte, repetitive Ausführung\nverkörpern.\nDie Installation "Das haben wir schon\nimmer so gemacht, da konnt ja jeder\nkommen" ist somit mehr als eine\nAnsammlung von Objekten. Sie ist ein\nscharfer Kommentar zu den absurden\nLogiken, die sich in bürokratischen\nSystemen manifestieren können, und\neine Reflexion über die menschliche\nTendenz, sich in selbstgeschaffenen\nOrdnungen zu verfangen.\n\n\n',
  "Wille und Vorstellung (2018)":
    '\nDer Altar der Vernunft: Eine\nalternative Darstellung des\nAbendmahls\nIn dieser radikalen Neuinterpretation\ndes Letzten Abendmahls unternimmt\nder Künstler Thomas Richartz den\ngewagten Versuch einer Synthese\nzwischen zwei scheinbar\nunvereinbaren Welten: dem\nchristlichen Glaubensmythos und der\npessimistischen Philosophie Arthur\nSchopenhauers, insbesondere\nseinem Hauptwerk "Die Welt als Wille\nlkonographie und stellt die\ntheologische Erzählung auf eine\nphilosophische Probe.\n\nDas Herzstück der Installation bildet\ndas Altarbild "Der göttliche Wille". Es\nist eine abstrakte Komposition, die\nbewusst die menschliche Gestalt des\nGöttlichen ablehnt. Stattdessen\nvisualisiert Richartz das, was\nSchopenhauer als den\nmetaphysischen Willen” bezeichnet\n— eine blinde, ziellose und\nunaufhörliche Kraft, die die Welt\nantreibt. Die Komposition besteht aus\neinem komplexen Geflecht runder\nund eckiger Formen. Die runden,\norganischen Elemente können als\n“weiblich" interpretiert werden, sie\nsymbolisieren das Formlose,\nFlieBende und Lebensspendende. Die\nscharfen, eckigen Formen stehen\ndagegen für das "Männliche" — für\nStruktur, Ratio und die oft\nschmerzhafte Individualisierung, die\nder Wille hervorbringt. Dieses\nAltarbild ist kein Abbild eines\ngnädigen Gottes, sondern eine\nvisuelle Darstellung der Spannungen\nund Konflikte, die dem Dasein\ninnewohnen. Es ist ein Akt der\nSchöpfung, der nicht auf göttlicher\nLiebe, sondern auf dem blinden,\nunerbittlichen Willen beruht.\nUm dieses Altarbild gruppieren sich\ndie 12 Apostelfiguren. Auch sie sind\nkeine naturalistischen Darstellungen,\nsondern Skulpturen aus ähnlichen\nabstrakten Elementen wie das\nAltarbild. Sie verkörpern die\nmenschliche Erfahrung, die aus der\ngrundlegenden Einheit des "Willens"\nheraus entsteht, aber in der\nIndividualitat gefangen ist.\nSchopenhauer sah die Welt der\nErscheinungen als eine Illusion, die\ndurch das "Principium\nIndividuationis" (das Prinzip der\nVereinzelung) entsteht.\nDie Apostel-Skulpturen sind somit\nweniger Personen als vielmehr\nManifestationen dieses Prinzips -\nindividuelle Ausformungen des\ngleichen Ur-Willens. Sie stehen nicht\nfür die Gemeinschaft der Gläubigen\num einen Heilsbringer, sondern für\ndie vereinzelten Leidenden, die in der\nWelt als Vorstellung gefangen sind.\nRichartz schafft mit dieser Installation\neinen philosophischen Altar, der die\ngängige Interpretation des Letzten\nAbendmahls — die Stiftung der\nEucharistie als Zeichen der Erlösung\n— hinterfragt. Statt der Hoffnung auf\nErlösung durch Glauben bietet er eine\nReflexion über die Natur des Seins\nselbst: das Dasein als ein unendliches\nRingen des Willens. Die Installation ist\neine Aufforderung, das Abendmahl\nnicht als mythologisches Ritual,\nsondern als ein philosophisches\nRätsel zu begreifen, das die Dualitat\nvon Leid und Wille, von Illusion und\nRealitat neu beleuchtet. Es ist eine\nDarstellung, die den Glauben nicht\nleugnet, sondern ihn durch die Linse\ndes pessimistischen Idealismus\nbetrachtet und eine neue,\ntiefgründige Perspektive auf eine der\nzentralen Szenen der christlichen\nTradition eröffnet.\n\n\n\n\n\n\n\n\n\n\n\n',
  "Freiheitskampf (2018)":
    "\nFreiheitskampf (2017)\n\nEin Band aus Licht und Schatten, eine\nAbfolge geheimnisvoller Zeichen, die\nsich ineinander verflechten und zu\neiner stummen Erzählung verdichten.\nThomas Richartz' Werk ist ein\nDenkmal des Widerstands, in dem\nsich die Kraft des Ringens und der\nWille zur Freiheit in abstrakter Form\nmanifestieren. Die Linien tanzen,\nbrechen und vereinen sich, schaffen\neine visuelle Chiffre, die von\nunauslöschlichen Spuren der\nVergangenheit zeugt. Es ist ein\nzeitloses Echo, das in der tiefen\n\nsich ineinander verflechten und zu\neiner stummen Erzählung verdichten.\nThomas Richartz' Werk ist ein\nDenkmal des Widerstands, in dem\nsich die Kraft des Ringens und der\nWille zur Freiheit in abstrakter Form\nmanifestieren. Die Linien tanzen,\nbrechen und vereinen sich, schaffen\neine visuelle Chiffre, die von\nunauslöschlichen Spuren der\nVergangenheit zeugt. Es ist ein\nzeitloses Echo, das in der tiefen\nAsthetik des\nSchwarz-WeiB-Kontrastes die Essenz\neines andauernden Kampfes festhält.\n\n",
  "Der Schein trügt (2018)":
    "\nThomas Richartz - Die heilige\nFamilie\n\nTeil der Gemeinschaftsausstellung\nDer Schein trügt, Ost-Stern Frankfurt\n\nMit Die heilige Familie präsentiert\nThomas Richartz eine Assemblage,\ndie den Dialog zwischen künstlichen\nund natürlichen Formen in eine\nfragile Balance bringt. Die\nSkulpturengruppe vereint\norganische Elemente mit\ngeometrischen Strukturen, als ob\nbeide Sphären auf der Suche nach\neiner gemeinsamen Harmonie waren.\nDiese Harmonie ist jedoch nicht\nselbstverständlich, sondern bewusst\ninszeniert: Alle Objekte sind in\nFrischhaltefolie eingehüllt. Diese\ntransparente Schicht konserviert\nnicht nur die Materialien, sondern\nverleiht ihnen eine einheitliche,\nglänzende Oberfläche - ein\nkünstlicher Schleier, der das\nNatürliche und das Menschengemachte\nvisuell verbindet.\n\nDie Folie wirkt zugleich schützend\nund entfremdend. Sie konserviert,\nindem sie distanziert. So wird der\nTitel Die heilige Familie zum\npoetischen wie ironischen\nKommentar über Zusammenhalt,\nSchutz und die fragile Schönheit\nvon Verbundenheit — immer\ngefährdet, immer von einer dünnen\nMembran zwischen Nähe und\nIsolation wechselnd.\n\n\nThomas Richartz - Die heilige\nFamilie\n\nTeil der Gemeinschaftsausstellung\nDer Schein trügt, Ost-Stern Frankfurt\n\nIn Die heilige Familie formt Thomas\nRichartz eine stille Szene, in der das\nNatürliche und das Künstliche in\neinem prekären Gleichgewicht\nverweilen. Steine, organische\nFragmente und menschengemachte\nFormen treten in einen Kreis aus\nstiller Nähe — wie Angehörige, die in\nihrer Verschiedenheit dennoch eine\ngemeinsame Aura teilen.\n\n\nDie Folie wirkt zugleich schützend\nund entfremdend. Sie konserviert,\nindem sie distanziert. So wird der\nTitel Die heilige Familie zum\npoetischen wie ironischen\nKommentar über Zusammenhalt,\nSchutz und die fragile Schönheit\nvon Verbundenheit — immer\ngefährdet, immer von einer dünnen\nMembran zwischen Nähe und\nIsolation durchzogen.\n\n\nThomas Richartz - Die heilige\nFamilie\n\n\nEin Kreis aus Formen.\n\nStein und Stahl, gewachsen und\ngemacht.\n\nUmhüllt vom Atem dünner Folie,\nbewahrt und gebannt\n\nin einem Glanz, der wärmt und\ntrennt.\n\nDie Haut der Dinge spricht von\nNähe,\n\ndoch hält sie Abstand.\n\nEin heiliger Bund,\n\ngeborgen in der Hand des Scheins,\nder das Vergängliche\n\nfür einen Augenblick\n\nunsterblich macht.\n\n\n\nDer Schein trügt\n\nOststern Frankfurt, 5.-7. Oktober\n2018\n\nMit Die heilige Familie präsentiert\nThomas Richartz eine Assemblage,\ndie den Dialog zwischen künstlichen\nund natürlichen Formen in eine\nfragile Balance bringt. Die\nSkulpturengruppe vereint\norganische Elemente mit\ngeometrischen Strukturen, als ob\nbeide Sphären auf der Suche nach\neiner gemeinsamen Harmonie\nwären. \n\n\n\nIn Die heilige Familie formt Thomas\nRichartz eine stille Szene, in der das\nNaturliche und das Kunstliche in\neinem prekaren Gleichgewicht\nverweilen. Steine, organische\nFragmente und menschengemachte\nFormen treten in einen Kreis aus\nstiller Nahe — wie Angehdrige, die in\nihrer Verschiedenheit dennoch eine\ngemeinsame Aura teilen.\n\nÜberzogen von einer hauchdünnen\nSchicht Frischhaltefolie erhalten die\nObjekte eine einheitliche,\nschimmernde Haut Sie konserviert,\nbewahrt, schützt und trennt\nzugleich. Das Glänzen der Folie lässt\ndie Materialien wie eingefroren\nwirken, eingefangen in einem\nMoment jenseits der Zeit. Hier wird\ndas Rohe geglättet, das Zufällige in\nForm gezwungen das Vergängliche\ndem Schein von Dauer unterworfen.\n\n\nDer Titel Die heilige Familie öffnet\ndabei ein Spannungsfeld zwischen\nIntimität und Inszenierung. Er\nevoziert Bilder von Geborgenheit,\nRitual und Verbundenheit, doch der\nkünstliche Schleier erinnert daran,\ndass Harmonie oft Ergebnis von\nGestaltung, ja, von bewusster\nInszenierung ist. Zwischen Nähe\nund Distanz, Echtheit und\nOberfläche entfaltet sich ein leiser\nKommentar über das menschliche\nBedürfnis, die Welt zu ordnen — und\nsie zugleich vor ihrem Verfall zu\nbewahren.\n\n \n\nOst-Stern/Frankfurt\nDie heilige Familie:\n\n\nEin Kreis aus Formen.\n\nStein und Stahl, gewachsen und\ngemacht.\n\nUmhüllt vom Atem dünner Folie,\nbewahrt und gebannt\n\nin einem Glanz, der wärmt und\ntrennt.\n\nDie Haut der Dinge spricht von\nNahe,\n\ndoch hält sie Abstand.\n\nEin heiliger Bund,\n\ngeborgen in der Hand des Scheins,\nder das Vergängliche\n\nfür einen Augenblick\n\nunsterblich macht.\n\n\n\n\n\n\n\n",
  "Reformation (2017)":
    '\nThomas Richartz: Installation\n"Reformation" (2017)\n\nAnlässlich des 500. Jahrestages des\nBeginns der Reformation schuf\nThomas Richartz 2017 die Installation\n"Reformation", ein vielschichtiges\nWerk, das die Kernwerte des\nhistorischen Wandels in eine\nzeitgenössische künstlerische\nSprache übersetzt. Richartz\' Arbeit\nversteht sich nicht als historisierende\nDarstellung, sondern als eine\nkritische Auseinandersetzung mit den\nspirituellen Idealen der Reformation\nund ihrer Relevanz in der heutigen\nZeit.\nDie Installation ist eine\nspannungsvolle Gegenüberstellung\nzweier visueller Welten. Im oberen Teil\nder Installation schweben eine\nVielzahl von Lautsprechern, die durch\nein scheinbar fragiles Geflecht aus\nhellen Holzlatten und Seilen\nmiteinander verbunden sind. Diese\nInstallation erinnert an eine\ndekonstruierte Kirchendecke oder\neinen Kronleuchter, der die\ntraditionelle Ordnung aufbricht. Die\nLautsprecher, obwohl ungenutzt,\nstehen fur die Verbreitung des\nWortes und des Gedankens, ein\nzentrales Element der Reformation.\n\n\n\nObjekten, die an Orgelpfeifen oder\nSäulen erinnern. Diese Elemente sind\nin einer geraden, fast militärisch\nanmutenden Formation aufgestellt\nund wirken massiv und unbeweglich.\nDie vier schwarzen Behälter davor\nsind gefüllt mit Bauschutt und\nRestmaterial, was auf Zerstörung und\nVerfall hindeutet, aber auch auf die\nNotwendigkeit, Altes loszulassen, um\nPlatz für Neues zu schaffen. Dieses\nArrangement repräsentiert die\nStagnation durch strenge\nHierarchie, Disziplin und\ndogmatische Autorität, wie sie in der\ntraditionellen Kirche über\n\nJahrhunderte vorherrschte.\nDurch diese Dualität schafft Richartz\neinen Dialog zwischen zwei\nentgegengesetzten Kräften. Er stellt\ndie ersehnte spirituelle Freiheit und\nToleranz, symbolisiert durch die\nschwebenden Lautsprecher, der\nstarren Dogmatik und dem Zwang der\ntraditionellen Macht entgegen. Die\nInstallation ist eine visuelle Metapher\nfur den Kampf zwischen Erneuerung\nund Tradition, zwischen der\nLeichtigkeit des Geistes und der\nSchwere der Materie. "Reformation"\nist somit mehr als eine Hommage an\n\n\n\n\ndie Geschichte; es ist ein Plädoyer für\neinen ständigen Wandel, der es dem\nEinzelnen ermöglicht, sich von\ngeistigen Fesseln zu befreien und\neinen Weg zu finden, der nicht durch\nDogma, sondern durch innere\nÜberzeugung bestimmt wird.\n\nErgänzung:\n\nDas ist eine hervorragende und sehr\npräzise Beschreibung der Symbolik in\nThomas Richartz\' Installation\n“Reformation”. Sie ergänzt den\nbereits verfassten Katalogtext\nperfekt. Die von Ihnen genannten\nDetails verdeutlichen die visuelle\nSprache des Künstlers und machen\ndie Intention des Werkes noch\ngreifbarer.\nDie starre Dogmatik und strenge\nHierarchie der klassischen Kirchen ist\ndurch Putzkübel mit Ziegelsteinen\nund gebundene, geordnet an der\nWand lehnende Bündel mit\nDachlatten symbolisiert.\nDemgegenüber schweben leere\nPutzeimer und entfesselte, frei\ntanzende Dachlatten an der Decke,\ndie wiederum für reformierte,\nindividuelle Glaubensfindung und\nSpiritualität stehen.\nIhr Beitrag vertieft das Verständnis\nder Arbeit erheblich und zeigt, wie\nRichartz konkrete Alltagsmaterialien\nin kraftvolle, symbolische Elemente\nverwandelt, um eine abstrakte Idee\nwie die Reformation greifbar zu\nmachen. Die Gegensätze von\ngefesselter Strenge und\nschwebender Freiheit werden durch\ndiese Materialien unmittelbar spürbar.\n\n\n\n\n\n\n',
  "Gerüchteküche (2017)":
    '\n"Gerüchteküche" von Thomas\nRichartz:\nThomas Richartz\' "Gerüchteküche"\ntaucht den Betrachter in eine\nverstörende, schwarz-weiße Szenerie\nein, die das Konzept eines Raumes —\nin diesem Fall einer Küche —- neu\ninterpretiert. Der Titel spielt auf die\numgangssprachliche Bedeutung des\nWortes an, die einen Ort beschreibt,\nan dem Gerüchte und Klatsch\nentstehen und sich verbreiten.\n\n\nRichartz\' Werk visualisiert diese Idee\nauf beunruhigende Weise. Die Wände\nscheinen von einer organisch-bizarr\nwuchernden Struktur bedeckt zu\nsein, die an ein Geflecht aus\nzerknülltem Papier, Stoff oder sogar\neinem Pilzbefall erinnert. Es ist ein\nChaos, das sich seinen Weg durch\nden Raum bahnt, ein visuelles\nAquivalent zu der Unordnung und\nZersetzung, die Gerüchte anrichten\nkönnen.\n\n\nDie monochrome Farbgebung\nverstärkt die düstere und unheimliche\nAtmosphäre. Licht und Schatten sind\nstark kontrastiert, was die\nOberflächenstruktur der\nWucherungen betont und den Raum\nin eine unwirkliche, fast\nalbtraumhafte Dimension verschiebt.\nDie offene Tür links im Bild lädt nicht\nzu einem friedlichen Eintritt ein,\nsondern wirkt eher wie ein Portal in\neine noch tiefere Dunkelheit oder\neinen Ausweg, der möglicherweise\nversperrt ist.\n\n\n"Gerüchteküche" ist mehr als die\nDarstellung eines realen Raumes; es\nist eine Metapher für die menschliche\nPsyche und die Dynamik sozialer\nInteraktionen. Richartz\' Installation ist\neine Reflexion über die zerstörerische\nKraft des Ungesagten, des\nVerfälschten und des Unsicheren, die\nsich in einer physischen Umgebung\nmanifestiert. Es ist eine eindringliche\nMahnung, die den Betrachter dazu\nanregt, über die unsichtbaren\nStrukturen nachzudenken, die unser\nMiteinander bestimmen.\n\n',
  "Das verlorene Jahr (2017)":
    '\n"Das verlorene Jahr" von\nThomas Richartz\nThomas Richartz\'s Installation "Das\nverlorene Jahr" ist eine ergreifende\nund kraftvolle Auseinandersetzung\nmit der verstrichenen Zeit und der\nsubjektiven Erfahrung eines Jahres,\ndas als ungenutzt oder verschwendet\nempfunden wird. Der Künstler schafft\neine physische Repräsentation dieses\nabstrakten Konzepts und lädt die\nBetrachter ein, sich dem Gewicht\nverlorener Zeit auf eine greifbare\nWeise zu stellen.\n\nWeise zu stellen.\nIm Zentrum der Installation stehen\n365 sorgfältig gefaltete\nPapierschiffchen, von denen jedes\neinen Tag des Jahres symbolisiert.\nDiese fragile Flotte, die in einer\nlangen, sich windenden Linie\nangeordnet ist, repräsentiert den\nunaufhaltsamen Marsch der Zeit,\neinen Strom von Tagen, der in diesem\nKontext keine nennenswerte Fracht\ntrug. Die Zerbrechlichkeit der\nPapierschiffchen unterstreicht die\nVergänglichkeit und oft flüchtige\nNatur unseres täglichen Lebens.\n\nDie Wochen werden durch 56\nschwarze Mullsacke markiert. Diese\nGegenstande, die typischerweise mit\nAbfall und Entsorgung assoziiert\nwerden, dienen als eine drastische\nund schwere Metapher für die\nWochen, die beiseite geworfen\nwurden. Ihre schiere Masse und\ndunkle, imposante Präsenz stehen in\nstarkem Kontrast zu den kleinen,\nweißen Papierschiffchen und deuten\nauf eine wachsende Last und\nVerzweiflung hin, wahrend sich die\nWochen anhäufen.\n\n\nWeiter entlang des Weges\nrepräsentieren 12 leere, schwarze\nMörtelkübel die Monate. Diese\nIndustriebehälter, die normalerweise\nmit Material zum Bauen gefüllt sind,\nwerden hier hohl gelassen. Ihre Leere\nsymbolisiert den Mangel an\nProduktivität oder Erfüllung, den der\nKünstler mit diesem speziellen Jahr in\nVerbindung bringt. Die dunklen,\nhöhlenartigen Raume in jedem Kübel\nspiegeln das Gefühl einer Leere\nwieder, einer Zeitspanne, in der kein\nFundament gelegt und nichts\naufgebaut wurde.\n\n\nSchließlich wird die Installation von\nvier schwarzen Leinwänden gerahmt,\ndie jeweils eine Jahreszeit darstellen.\nDiese Leinwände sind keine Gemälde\nim herkömmlichen Sinne; sie sind\nvollständig schwarz, frei von Bild oder\nFarbe. Diese Abwesenheit visueller\nInformationen deutet auf ein Jahr hin,\ndas ohne die lebhaften\nVeränderungen und\nunverwechselbaren Qualitaten\nverging, die typischerweise mit den\nJahreszeiten verbunden sind. Sie\nrepräsentieren eine monolithische,\neinförmige Zeitspanne, in der die\nzyklische Schönheit der Natur\nunbemerkt oder ungelebt blieb.\n\n\nDurch diese sorgfältige Anordnung\nalltäglicher Gegenstande wird "Das\nverlorene Jahr" zu einem meditativen\nRaum. Der Betrachter wird physisch\nauf dem Weg eines Jahres geführt\nund mit der eskalierenden Symbolik\nseines Verlaufs konfrontiert — von den\nkleinen, hoffnungsvollen Anfangen\neines einzigen Tages bis zur finalen,\nweiten Leere der Jahreszeiten.\nRichartz verwandelt die universelle\nErfahrung der Zeit in eine persönliche\nund zutiefst berührende Reise und\nregt zu einer eindringlichen Reflexion\ndarüber an, wie wir unsere\nwertvollste Ressource messen,\nnutzen und letztendlich verlieren.\n\n\n\n\n',
  "Berlin gibt auf (2015)":
    '\nThomas Richartz: "Berlin gibt auf"\n\nDas monumentale Acryl-Gemälde\n"Berlin gibt auf" von Thomas\nRichartz, das sich Uber eine Flache\nvon 30 Quadratmetern erstreckt, ist\neine schonungslose\nBestandsaufnahme der Berliner\nKunstszene. Das Werk ist ein visuelles\nEpos, das den gnadenlosen Kampf\n"Jeder gegen Jeden" in dieser als\nkreativ und frei verklärten Welt in den\nFokus rückt. Richartz entwirft auf der\nriesigen Leinwand ein Schlachtfeld,\nauf dem Träume und Ambitionen mit\nbrutaler Realität kollidieren.\n\n\nAnstatt eine romantische oder\nidealisierte Vorstellung von Berlin als\nZufluchtsort fir Künstler zu malen,\nzeigt Richartz die Schattenseiten: den\nunerbittlichen Konkurrenzkampf um\nAnerkennung, Galerien, Fördermittel\nund die schlichte finanzielle Existenz.\nDie Komposition ist von einer rauen,\nexpressiven Dynamik gepragt, die die\nIntensitat und den Druck des\nUberlebenskampfes widerspiegelt.\nDie Farbpalette ist oft düster und\nerdig, durchbrochen von grellen,\nunheimlichen Farbakzenten, die\nMomente der Verzweiflung, des Neids\nund der Aggression symbolisieren.\n\n\nDie enormen Dimensionen des\nGemäldes sind kein Zufall; sie\nzwingen den Betrachter, Teil dieser\nchaotischen Szenerie zu werden. Die\nphysische Präsenz des Werkes\numhüllt den Raum und spiegelt die\nallgegenwärtige, erdrückende\nAtmosphäre wider, die in der Szene\nherrschen kann. In den komplexen\nSchichtungen der Acrylfarbe lassen\nsich Andeutungen von anonymen\nGesichtern, zersplitterten Formen und\nfragmentierten Erzählungen finden,\ndie die Isolation trotz der Masse\nillustrieren. Richartz verzichtet auf\neine klare, gegenständliche\n\neine klare, gegenständliche\nDarstellung und setzt auf eine\ngestische, fast eruptive Malweise, die\ndie emotionale Turbulenz des Themas\nunmittelbar vermittelt.\n“Berlin gibt auf" ist somit kein Bild der\nResignation, sondern ein mutiges,\nschonungsloses Statement. Es ist\neine künstlerische\nAuseinandersetzung mit den Mythen\nund der harten Realität der\nKunstproduktion in einer Metropole,\ndie ihre Talente oft erst ausbrennt,\nbevor sie sie anerkennt. Das Werk\nfordert dazu auf, die romantische\n\n\nVorstellung der Kunstszene zu\nhinterfragen und die verborgenen\nKämpfe und Opfer sichtbar zu\nmachen, die hinter jedem\nscheinbaren Erfolg stecken. Es ist ein\nkraftvolles Manifest gegen die\nOberflächlichkeit und eine Hommage\nan die unerbittliche Leidenschaft, die\ntrotz allem Widerstand in Berlin\nweiter existiert.\n\n\n',
  "Der Himmel über Peking (2014)":
    "\nThomas Richartz: Der Himmel über\nPeking / konservierter Verfall (2014)\n\nDie Werkreihe ,,Der Himmel über\nPeking / konservierter Verfall”\nkonfrontiert den Betrachter mit der\nvergänglichen Schönheit der Natur,\ndie in einem Zustand des Stillstands\nund der künstlichen Konservierung\nfestgehalten wird. Die Arbeit spielt\nmit dem Paradoxon des Titels und der\nvisuellen Komposition: Ein Bild des\nHimmels, der oft als Symbol für Weite\nund Freiheit steht, wird mit dem\nkonkreten Bild des Verfalls\nverbunden, das in Peking auch als\nMetapher für die Umweltprobleme\nder Großstadt interpretiert werden\nkann.\nIm Zentrum der Arbeit stehen\nFundstücke der Natur — verwittertes\nGestrüpp, Äste und Wurzeln - die\nnicht mehr leben, aber durch die\nkünstlerische Geste eine neue\nExistenz erhalten. Diese organischen,\nzerbrechlichen Formen sind auf\nRettungsfolie gebettet, die an eine\nNotlage erinnert, und dann sorgfältig\nin transparente Stretchfolie gewickelt.\nDieser Akt der Konservierung friert\nnicht nur den physischen Zustand des\nVerfalls ein, sondern schafft auch\neine neue, skulpturale Qualität. Die\nStretchfolie wird zu einer\nschützenden Membran.\n\nDie einzelnen, in einem Raster\nangeordneten Tafeln wirken wie\narchäologische Fundstücke oder\nbotanische Präparate, die in einem\nLabor der Kunst untersucht werden.\nSie zeigen die Spuren der Zeit —-\nRisse, Knoten und Verformungen — in\neiner Ästhetik, die sowohl beruhigend\nals auch verstörend ist. Richartz lädt\nden Betrachter ein, Über die\nBeziehung zwischen Natur und\nMensch, Vergehen und Erhaltung,\nsowie über die Rolle der Kunst als\nKonservator von Augenblicken\nnachzudenken. Die Arbeit ist somit\nein stilles, meditatives Mahnmal für\ndie Schönheit im Verfall und die\nVergänglichkeit des Lebens, die\ndurch die menschliche Hand eine\nneue, konservierte Form erhält.\n\n\nThomas Richartz: Der Himmel über\nPeking / konservierter Verfall (2014)\n- Eine poetische Betrachtung:\n\n\nDer Himmel Uber Peking, ein fernes\nVersprechen,\nwird zum Rahmen für das, was\nvergeht.\nÄste, verdorrt, vom Wind gezeichnet,\nein feines Geäst der Einsamkeit.\nSie liegen gebettet auf silberner\nHaut,\nauf einem Mantel, der Notfall flüstert.\nDann die Umarmung des Glanzes,\nklar und fest,\nein Kokon aus Plastik, der sie rettet.\nDer Verfall ist eingefroren, ein stiller\nTanz,\ndie Zeit erstarrt in Falten und Rissen.\nJeder Ast eine Linie, jedes Blatt ein\nSchatten,\nkonserviert in der Stille eines\nunerhörten Moments.\nHier stirbt die Natur und wird zum\nDenkmal.\nEin Museum für das, was war, bevor\nes ging.\nDie Wurzeln, die einst griffen, die\nAste, die strebten,\nnun Zeugen eines Himmels, der sie\nnur noch in Folie sieht.\n\n\n\n\n",
  "Hallgatas (2014)":
    '\nThomas Richartz: Hallgatas (2014)\n\n\nDie Installation "Hallgatas" (ungarisch\nfür "Schweigen") entstand anlässlich\ndes Gedenkens an die Opfer des\nungarischen Aufstands von 1956\ngegen die Besatzung durch die\nsowjetische Rote Armee. Das Werk\nsetzt sich mit dem Spannungsfeld\nzwischen Individualität (Vereinzelung)\nund Kollektivismus auseinander.\nDie Installation besteht aus zwei\nElementen, die in einen visuellen und\nkonzeptuellen Dialog treten:\n\n1. Das Kollektiv: 13 abgehängte\nKirchenglocken, die vor der\nKathedrale von Esztergom (Ungarn) in\nStretchfolie verpackt wurden. Sie\nsymbolisieren die Macht des\nKollektivs, die jedoch durch die\nEinwickelung in Folie an ihre\nursprüngliche Funktion und ihren\nKlang beraubt, fast zum\nSchweigen gebracht wird.\n\n\n2. Das Individuum: 200 in\nStretch-Folie gewickelte\nDonausteine, die den verpackten\nGlocken gegenübergestellt sind.\nJeder Stein steht für die\nVereinzelung des Individuums,\nrepräsentiert aber in seiner Masse\nauch eine Form des Kollektivs. Die\nVerpackung der Steine\nunterstreicht die Isolation des\nEinzelnen und dient zugleich als\nästhetisches Element, das die\nOberflächenstruktur der\nInstallation prägt.\nDurch die Gegenüberstellung dieser\nElemente — der imposanten Glocken\nals Sinnbild einer schweigenden\nkollektiven Kraft und der zahlreichen\nindividuellen Steine - reflektiert\n"Hallgatas" nicht nur das historische\nEreignis von 1956, sondern auch\ngrundlegende gesellschaftliche\nFragen über die Rolle des Einzelnen in\nder Gemeinschaft und die Ambivalenz\nvon Stärke und Stummheit. Die Arbeit\nwird so zu einem Mahnmal des\nSchweigens und des Widerstands,\ndas die Erinnerung wachhält, ohne\nlaut zu sein.\n\n\nThomas Richartz: Hallgatas (2014) -\nPoetische Betrachtung:\n\n\nDie Glocken, stumm verhüllt im fahlen\nGlanz der Kathedrale.\nDreizehn Körper, einst Stimme des\nHimmels, nun gefangen in Folie.\nSie schweigen, ein Echo des\nWiderstands, der in der Stille\nwiderhallt.\nDas Kollektiv, das seinen Ruf verlor,\ngehüllt in ein Gedächtnis aus Plastik.\nAm Boden, ein Meer aus Stein,\ngeboren aus der Donau Tiefe.\nZweihundert Individuen, umhüllt von\neiner zweiten Haut,\njeder für sich allein, in seinem\neigenen Licht gefangen.\nSie sind das Schweigen, das in der\nMasse flüstert,\nein Teppich aus Erinnerungen, die\nsanft am Ufer liegen.\nVereinzelung trifft Kollektiv, im\nSpannungsfeld von Stille und Macht.\nHallgatas — ein Atemzug des\nSchweigens, das mehr sagt \nals jeder Ton.\nEin Mahnmal für die Toten, verpackt\nin der Schönheit des Vergessens,\nein Dialog zwischen Stein und Metall,\nzwischen Seele und Masse.\nEin stummes Gebet, das in der Hülle\nschimmert und uns aufweckt.\n\n',
  "Religionsunterricht (2013)":
    "\nReligionsunterricht\n(2013-2014)\n\nZwölf Bilder über Glaube, Macht\nund Bilderverbot\n\nIn der Werkreihe Religionsunterricht\n(2013-2014) stellt Thomas Richartz\nzentrale Bildwelten verschiedener\nWeltreligionen in einen\nvielschichtigen Zusammenhang. Die\nzwölf großformatigen Acrylgemälde\nvereinen sakrale Ikonen,\narchetypische Figuren und\nsymbolische Motive aus Judentum,\nChristentum, Islam, Buddhismus\nund anderen Glaubenssystemen —\neingefasst in ein streng vertikal\ngegliedertes Grundraster.\n\nDiese Gitterstruktur, die die\ngesamte Serie durchzieht, wirkt wie\nein Filter oder ein Käfig — ein\nformaler Kommentar zur\nBegrenztheit menschlicher\nVorstellungskraft, aber auch zur\nInstitutionalisierung des Glaubens.\nDie ausdrucksstarken, oft\nverknoteten Linienmuster erinnern\nan kalligrafische Zeichen,\nverschlungene Schriftrollen oder\nornamentale Heilige Texte - sie\nverbinden das Bildhafte mit dem\nUnaussprechlichen.\n\n\nReligionsunterricht (2013-2014)\n\nIn zwölf großformatigen\nAcrylbildern setzt sich Thomas\nRichartz mit sakralen Bildwelten\nverschiedener Religionen\nauseinander. Ikonen, Symbole und\nFigurendarstellungen werden durch\nein vertikales Raster gebrochen und\nin ein komplexes, ornamentales\nZeichensystem überführt. Der\nZyklus thematisiert den Umgang\nmit Glauben, Bildverbot und\nspiritueller Autorität — zwischen\nVerehrung und Befragung.\n\n\n",
  "Dystopie (2011)":
    '\nInstallation zur Ausstellung\n"Utopia"\n\nMit Dystopie (2011) realisierte\nThomas Richartz eine\nraumgreifende Installation als\nBeitrag zur Ausstellung "Utopia". Ein\n20 Meter langer Pfad aus\nschwarzem Sand, gesäumt von\ngrobem Betonbruch, führt auf eine\nskulpturale Formation aus\naufgetürmtem Bruchholz zu. Der\nWeg ist zugleich Bedrohung und\nVerheißung — eine Passage in eine\nungewisse Zukunft, in der\nnatürliche und künstliche\nMaterialien zu einem dystopischen\nGleichgewicht verschmelzen.\n\n\nDie Arbeit kommentiert das\nScheitern utopischer Entwurfe,\nderen ldealismus oft auf der\nVerdrängung realer Bedingungen\nberuht. Der schwarze Sand steht für\nverbrannte Hoffnung, der Beton für\nzerschellte Konzepte, das Holz für\ndas fragile Überleben im\nWiderstand.\nDystopie ist keine einfache\nWarnung, sondern ein begehbares\nSinnbild für den Konflikt zwischen\nVision und Wirklichkeit — still,\nmonumental, eindringlich.\n\n\n\nDystopie (2011)\n\nEin 20 Meter langer Pfad aus\nschwarzem Sand, flankiert von\nBetonbruch, führt in eine Skulptur\naus Bruchholz. Die Installation\nentstand für die Ausstellung\n"Utopia" als kritischer Kommentar\nzum Scheitern idealistischer\nKonzepte. Thomas Richartz\nformuliert mit einfachen Materialien\nein eindrucksvolles Sinnbild für die\nKollision von Idee und Realität.\n\n',
  "Baudelaire (2009-2012)":
    '\nBaudelaire (2003-2012)\nRadierungen nach ,,Les Fleurs du\nmal“ von Charles Baudelaire\n\nIn dieser Werkreihe widmet sich\nThomas Richartz dem poetischen\nKosmos von Charles Baudelaire.\nZwischen 2003 und 2012 entstand\nein vielschichtiger Zyklus von\nRadierungen, die Bild und Wort in\neinen spannungsvollen Dialog\nsetzen. Die Titel der Arbeiten sind\ndirekt aus Baudelaires Hauptwerk\nLes Fleurs du mal entnommen -\neinem Meilenstein der modernen\nDichtung, dessen existenzielle\nTiefenscharfe und symbolistische\nBildsprache bis heute faszinieren.\n\n\nRichartz antwortet auf diese\nliterarische Welt mit einer eigenen,\ngrafisch verdichteten\nFormensprache. Die Radierungen\nbewegen sich zwischen Figuration\nund Abstraktion, zwischen klaren\nLinien und nervös wuchernden\nTexturen. Gesichter, Gesten,\nArchitekturen und Schattenrisse\ntauchen aus einem dichten Netz aus\nLinien auf — wie Erinnerungen oder\nVisionen. Die Motive wirken wie\nFragmente eines inneren Dramas,\ndas sich ebenso auf das eigene\nErleben wie auf die psychologischen\nAbgründe Baudelaires bezieht.\n\nJede Radierung ist dabei nicht bloß\neine Illustration, sondern ein\neigenständiger Kommentar. Die Arbeiten\nnehmen die düstere Bildsprache\nund existenzielle Tiefe der Texte auf\nund übersetzen sie in grafische\nForm. In spannungsvoller Balance\nzwischen Linie und Fläche, Figur\nund Abstraktion entstehen Bilder,\ndie keine Illustrationen sind, sondern\nvisuelle Reflexionen über das\nDargestellte. Der Zyklus zeigt\nRichartz’ präzisen Umgang mit der\nLinie und seine Fähigkeit,\nliterarische Stimmungen in\nkraftvolle Bildwelten zu überführen.\n\n\n\nThomas Richartz - "Baudelaire"(2003-2012)\n\nRadierungen nach Les Fleurs du mal\nvon Charles Baudelaire\n\n\n\nMit dem Zyklus Baudelaire\n(2003-2012) legt Thomas Richartz\neine eindrucksvolle grafische\nAuseinandersetzung mit dem\nberühmten Gedichtband Les Fleurs\ndu mal vor. In über einem Jahrzehnt\nentstand eine Serie von\nRadierungen, die Baudelaires\nsymbolistische Bildsprache in\nexpressive Linien, kontrastreiche\nFlächen und rätselhafte Szenen\nüberfuhrt.\n\n\nRichartz verzichtet auf narrative\nIllustration — stattdessen entstehen\nvisuelle Zustandsbilder:\nVerdichtungen seelischer Raume,\nMomentaufnahmen psychologischer\nSpannungen. Die Arbeiten\nchangieren zwischen\narchitektonischer Strenge,\nfigürlicher Andeutung und\nabstrakter Überlagerung. Die Titel\nder Blätter — direkt aus Baudelaires\nGedichten entnommen - fungieren\nals poetische Resonanzraume für\neine eigenständige, visuell intensive\nInterpretation.\n\nDer Zyklus demonstriert Richartz’\nkünstlerische Handschrift in\nReinform: konzentriert, analytisch,\nexistenziell.\n\n\n\n',
  "LA BELLE ET LA BETE (2009)":
    '\n\nLa Belle et la Bete\n\n\nMit dem Titel in Anlehnung an Jean\nCocteaus poetischen Filmklassiker\nentfaltet Thomas Richartz in dieser\nSerie eine bildnerische Erzählung\nzwischen Anziehung und\nKonfrontation, Zartheit und Kraft.\nDie Werke spielen mit Gegensätzen\n— fließende Linien treffen auf\nkantige Strukturen, helle Flächen\nkontrastieren mit dunklen Schatten.\nWie im Film verschmelzen Traum\nund Wirklichkeit: figurative\nAndeutungen lösen sich in\nabstrakte Formen auf, ornamentale\nElemente treten neben rohe,\nspontane Gesten. Der Dialog von\n"Schönheit" und , "Bestie" wird nicht\nals moralisches Gleichnis inszeniert,\nsondern als visuelles Spannungsfeld,\nin dem beide Pole einander\nbedingen und bereichern.\n\nSo wird La Belle et la Bete bei\nRichartz zu einer Metapher für das\nkreative Ringen zwischen Ordnung\nund Chaos, Kontrolle und Ausdruck\n— ein Spiel der Kräfte, das sich auf\nder Leinwand in immer neuen\nKonstellationen entfaltet.\n\n\n',
};
